const ids = ['2:5','2:2','2:3','2:4'];
const out = [];
for (const id of ids) {
  const n = await figma.getNodeByIdAsync(id);
  if (!n) { out.push({id, missing:true}); continue; }
  const info = {id, name:n.name, type:n.type, w:n.width, h:n.height};
  if (n.type==='COMPONENT') {
    info.fills = n.fills;
    info.children = n.children.map(c=>({name:c.name,type:c.type,fill:c.fills,size:[c.width,c.height]}));
    info.vectorPaths = n.children.filter(c=>'vectorPaths' in c).map(c=>({name:c.name,vectorPaths:c.vectorPaths,strokeWeight:c.strokeWeight,strokes:c.strokes}));
    info.constraints = n.constraints;
  }
  out.push(info);
}
// fonts available
const fonts = await figma.listAvailableFontsAsync();
const dm = fonts.filter(f=>f.fontName.family.toLowerCase().includes('dm sans')).map(f=>f.fontName);
return JSON.stringify({out, dm}, null, 1);

