function rgb(h){h=h.replace('#','');return {r:parseInt(h.slice(0,2),16)/255,g:parseInt(h.slice(2,4),16)/255,b:parseInt(h.slice(4,6),16)/255};}
function fill(h,o){return h?[{type:'SOLID',color:rgb(h),opacity:o===undefined?1:o}]:[];}
