function T(chars,size,font,color,opts){
  opts=opts||{}; const t=figma.createText(); t.fontName=font; t.characters=chars; t.fontSize=size;
  t.fills=fill(color||INK); t.lineHeight={unit:'PIXELS',value:opts.lh||Math.round(size*1.4)};
  t.letterSpacing={unit:'PIXELS',value:opts.ls||0}; return t;
}
