function walk(n,acc,scr){
  if(n.reactions&&n.reactions.length) acc.push({screen:scr,name:n.name,chars:n.characters||'',to:n.reactions[0].actions[0].destinationId});
  if('children' in n) n.children.forEach(c=>walk(c,acc,scr));
  return acc;
}
